using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1. Strongly-typed metadata ──────────────────────────────────
// GetTypeInfo returns the non-generic JsonTypeInfo, but for types
// the resolver knows about the runtime object is always the
// generic JsonTypeInfo<T>, so the cast is safe.
JsonTypeInfo<Person> personInfo =
    (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));

Console.WriteLine($"Type:            {personInfo.Type.Name}");
Console.WriteLine($"Kind:            {personInfo.Kind}");
Console.WriteLine($"Properties:      {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

var json = JsonSerializer.Serialize(new Person("Ada", 37), personInfo);
Console.WriteLine($"Serialized:      {json}");

Person? roundTripped = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Round-tripped:   {roundTripped}");

// ── 2. Probe without throwing ───────────────────────────────────
// TryGetTypeInfo returns false instead of throwing when metadata
// is unavailable (e.g. the resolver doesn't cover that type or
// there's no resolver at all).
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new NullResolver()   // resolves nothing
};

if (emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"\nMetadata found:  {info.Type.Name}");
}
else
{
    Console.WriteLine($"\nNo metadata for {nameof(Person)} — and no exception was thrown.");
}

// Also show a successful probe for contrast.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2))
{
    Console.WriteLine($"Metadata found:  {info2.Type.Name} (from the real resolver)");
}

// ── Supporting types ────────────────────────────────────────────
record Person(string Name, int Age);

/// <summary>A resolver that deliberately resolves nothing.</summary>
sealed class NullResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

